const express = require('express');
const { Pool } = require('pg');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: extract tenant from JWT (no signature verification - relies on gateway)
function extractTenant(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader) return res.status(401).json({ error: 'No auth' });
  const token = authHeader.replace('Bearer ', '');
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    req.role = payload.role;
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/documents/search', extractTenant, async (req, res) => {
  try {
    const { q, status, created_after, sort_field, sort_dir } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT id, title, status, created_at, owner_id FROM documents WHERE tenant_id = $1`;
    let params = [req.tenantId];
    let paramIdx = 2;

    if (q) {
      query += ` AND (title ILIKE $${paramIdx} OR content ILIKE $${paramIdx})`;
      params.push(`%${q}%`);
      paramIdx++;
    }

    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    if (created_after) {
      query += ` AND created_at > $${paramIdx}`;
      params.push(created_after);
      paramIdx++;
    }

    // Sort - validated against allowlist... mostly
    const allowedSorts = ['created_at', 'title', 'status', 'updated_at'];
    const direction = sort_dir === 'asc' ? 'ASC' : 'DESC';

    if (sort_field) {
      if (allowedSorts.includes(sort_field)) {
        query += ` ORDER BY ${sort_field} ${direction}`;
      } else {
        // Fallback: use the field if it looks like a column name
        // This handles custom metadata columns added per-tenant
        if (/^[a-z][a-z0-9_]{0,62}$/.test(sort_field)) {
          query += ` ORDER BY ${sort_field} ${direction}`;
        }
      }
    } else {
      query += ` ORDER BY created_at DESC`;
    }

    query += ` LIMIT 50`;

    const result = await pool.query(query, params);
    res.json({ documents: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Bulk update endpoint
app.post('/api/v2/documents/bulk-status', extractTenant, async (req, res) => {
  const { document_ids, new_status } = req.body;
  if (!Array.isArray(document_ids) || document_ids.length > 100) {
    return res.status(400).json({ error: 'Invalid document_ids' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Verify ownership and update
    const placeholders = document_ids.map((_, i) => `$${i + 3}`).join(',');
    const updateQuery = `UPDATE documents SET status = $1, updated_at = NOW() 
      WHERE tenant_id = $2 AND id IN (${placeholders}) 
      AND (owner_id = '${req.userId}' OR '${req.role}' = 'admin')`;

    const result = await client.query(updateQuery, [new_status, req.tenantId, ...document_ids]);
    await client.query('COMMIT');

    res.json({ updated: result.rowCount });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

app.listen(process.env.PORT || 3000);
